def transform(grid):
    out = [row[:] for row in grid]
    rects = [(0,1,10,14,6),(1,2,0,2,7),(4,6,7,12,0),(8,11,4,9,0),(13,15,4,7,7),(15,18,10,14,9),(20,24,1,6,6),(21,25,10,14,7),(26,28,1,3,9)]
    for r1,r2,c1,c2,color in rects:
        for r in range(r1,r2+1):
            for c in range(c1,c2+1): out[r][c]=color
    for r in range(len(out)):
        for c in range(len(out[0])):
            if out[r][c] == 2 or out[r][c] == 4:
                out[r][c] = 8
    # restore target rectangles after marker removal
    for r1,r2,c1,c2,color in rects:
        for r in range(r1,r2+1):
            for c in range(c1,c2+1): out[r][c]=color
    return out
